export const APP_NAME = 'BörsVy';
export const APP_DESCRIPTION = 'Real-time Stock Market Tracker';

export const EXAMPLE_SYMBOLS = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA'];

export const API_ENDPOINTS = {
    SEARCH: '/api/stocks/search',
    FAVORITES: '/api/stocks/favorites',
};

export const ERROR_MESSAGES = {
    STOCK_NOT_FOUND: 'Stock not found',
    FETCH_FAILED: 'Failed to fetch data',
    ADD_FAILED: 'Failed to add stock to favorites',
    REMOVE_FAILED: 'Failed to remove stock from favorites',
};
